fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let mut lines: Vec<String> = if keepends {
                s.split_terminator('\n')
                    .map(|line| format!("{}\n", line)) // Retain the newline character
                    .collect()
            } else {
                s.split_terminator('\n')
                    .map(|line| line.to_string())
                    .collect()
            };

            // Ensure that each inner list is non-empty
            if lines.is_empty() {
                lines.push(String::new()); // Add an empty string if no lines were found
            }

            lines
        })
        .collect()
}